package com.troday.api.service;

import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.time.LocalDateTime; import java.util.*;

@Service public class MessagingService {
 @org.springframework.beans.factory.annotation.Autowired private DomainSupport domain;
 @org.springframework.beans.factory.annotation.Autowired private RealtimeHub hub;
 private final AccountService accounts; private final ConversationRepository conversations; private final ConversationParticipantRepository participants; private final ChatMessageRepository messages; private final NotificationRepository notifications; private final PostRepository posts; private final RoommateRequestRepository roommateRequests;
 public MessagingService(AccountService a,ConversationRepository c,ConversationParticipantRepository p,ChatMessageRepository m,NotificationRepository n,PostRepository posts,RoommateRequestRepository rr){accounts=a;conversations=c;participants=p;messages=m;notifications=n;this.posts=posts;roommateRequests=rr;}
 @Transactional public ApiResponseDto<?> roomInquiry(HttpServletRequest r,JsonNode b){
Long me=accounts.authenticatedUserId(r);Long postId=requiredLong(b,"postId");domain.jdbc.queryForList("SELECT id FROM posts WHERE id=? FOR UPDATE",postId);Post post=posts.findById(postId).filter(this::publicPost).orElseThrow(()->notFound("Tin không còn khả dụng"));if(me.equals(post.getLandlordId()))throw bad("Không thể tự mở hội thoại với chính mình");
        List<Long> ids=domain.jdbc.queryForList("SELECT conversation_id FROM api_room_inquiries WHERE post_id=? AND tenant_id=? AND landlord_id=? FOR UPDATE",Long.class,postId,me,post.getLandlordId());
        if(ids.isEmpty())ids=domain.jdbc.queryForList("SELECT c.id FROM conversations c WHERE c.post_id=? AND c.type='ROOM_INQUIRY' AND EXISTS(SELECT id FROM conversation_participants WHERE conversation_id=c.id AND user_id=?) AND EXISTS(SELECT id FROM conversation_participants WHERE conversation_id=c.id AND user_id=?) AND (SELECT COUNT(*) FROM conversation_participants WHERE conversation_id=c.id)=2 LIMIT 1 FOR UPDATE",Long.class,postId,me,post.getLandlordId());
        Conversation c=ids.isEmpty()?conversations.save(newConversation("ROOM_INQUIRY",post.getRoomId(),postId,null)):domain.current(Conversation.class,ids.get(0));
        ensureParticipant(c.getId(),me);ensureParticipant(c.getId(),post.getLandlordId());
        domain.jdbc.update("INSERT IGNORE INTO api_room_inquiries(post_id,tenant_id,landlord_id,conversation_id) VALUES (?,?,?,?)",postId,me,post.getLandlordId(),c.getId());domain.jdbc.update("UPDATE conversation_participants SET deleted=FALSE,archived=FALSE WHERE conversation_id=? AND user_id=? AND left_at IS NULL",c.getId(),me);return ok("POST",conversationData(c));
 }
 public ApiResponseDto<?> list(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);List<Map<String,Object>> out=participants.findByUserId(me).stream().filter(p->!p.isDeleted()&&!p.isArchived()&&participants.findByConversationId(p.getConversationId()).size()==2).map(p->conversations.findById(p.getConversationId()).map(this::conversationData).orElse(null)).filter(Objects::nonNull).toList();return ok("GET",out);}
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Conversation c=member(id,me);return ok("GET",conversationData(c));}
 public ApiResponseDto<?> messageList(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);member(id,me);return ok("GET",messages.findByConversationIdOrderBySentAtAscIdAsc(id).stream().map(this::messageData).toList());}
 @Transactional public ApiResponseDto<?> sendMessage(HttpServletRequest r,Long id,JsonNode b){
Long me=accounts.authenticatedUserId(r);Conversation c=member(id,me);ensureCanSend(c);String key=text(b,"clientMessageKey"),type=text(b,"type"),content=text(b,"content");
        if(key.isBlank()||!Set.of("TEXT","IMAGE").contains(type))throw bad("Cần clientMessageKey và type TEXT/IMAGE");if("TEXT".equals(type)&&(content.isBlank()||content.length()>2000))throw bad("Nội dung cần từ 1 đến 2000 ký tự");
        JsonNode fileIds=b.path("fileIds");if("IMAGE".equals(type)&&(!fileIds.isArray()||fileIds.isEmpty()||fileIds.size()>8))throw bad("Tin ảnh cần từ 1 đến 8 tệp CHAT_IMAGE");
        domain.jdbc.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",me);
        Optional<ChatMessage> old=messages.findBySenderIdAndClientMessageKey(me,key);if(old.isPresent()){ChatMessage m=old.get();List<Long> previous=domain.jdbc.queryForList("SELECT id FROM files WHERE chat_message_id=? ORDER BY id",Long.class,m.getId());List<Long> incoming=new ArrayList<>();if(fileIds.isArray())fileIds.forEach(f->incoming.add(f.asLong()));Collections.sort(incoming);if(!id.equals(m.getConversationId())||!type.equals(m.getMessageType())||!content.equals(Objects.toString(m.getContent(),""))||!previous.equals(incoming))throw conflict("Khóa tin nhắn đã được dùng với nội dung khác");return ok("POST",messageResult(m));}
        if(fileIds.isArray())for(JsonNode fid:fileIds){domain.activeFile(fid.asLong(),me,"CHAT_IMAGE");if(domain.exists("SELECT id FROM files WHERE id=? AND chat_message_id IS NOT NULL",fid.asLong()))throw conflict("Ảnh đã thuộc tin nhắn khác");}
        ChatMessage m=new ChatMessage();m.setConversationId(id);m.setSenderId(me);m.setClientMessageKey(key);m.setMessageType(type);m.setContent(content);m.setSentAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));m=messages.saveAndFlush(m);
        if(fileIds.isArray())for(JsonNode fid:fileIds)domain.jdbc.update("UPDATE files SET chat_message_id=? WHERE id=?",m.getId(),fid.asLong());publishMessage(c,m,me);return ok("POST",messageResult(m));
 }
 @Transactional public ApiResponseDto<?> readState(HttpServletRequest r,Long id,JsonNode b){
Long me=accounts.authenticatedUserId(r);member(id,me);Long messageId=requiredLong(b,"lastReadMessageId");ChatMessage m=messages.findById(messageId).orElseThrow(()->notFound("Không tìm thấy tin nhắn"));if(!m.getConversationId().equals(id))throw bad("Tin nhắn không thuộc hội thoại");Long pid=domain.jdbc.queryForObject("SELECT id FROM conversation_participants WHERE conversation_id=? AND user_id=? FOR UPDATE",Long.class,id,me);ConversationParticipant p=domain.current(ConversationParticipant.class,pid);
        if(p.getLastReadAt()==null||m.getSentAt().isAfter(p.getLastReadAt())){p.setLastReadAt(m.getSentAt());domain.jdbc.update("INSERT INTO api_conversation_read_cursors(conversation_id,user_id,last_message_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE last_message_id=VALUES(last_message_id)",id,me,messageId);}else if(m.getSentAt().equals(p.getLastReadAt()))domain.jdbc.update("INSERT INTO api_conversation_read_cursors(conversation_id,user_id,last_message_id) VALUES (?,?,?) ON DUPLICATE KEY UPDATE last_message_id=GREATEST(last_message_id,VALUES(last_message_id))",id,me,messageId);participants.saveAndFlush(p);return ok("PUT",Map.of("conversationId",id,"lastReadAt",p.getLastReadAt(),"unreadCount",unread(p,me)));
 }
 @Transactional public ApiResponseDto<?> preferences(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);member(id,me);ConversationParticipant p=participants.findByConversationIdAndUserId(id,me).orElseThrow();if(b.has("muted"))p.setMuted(b.get("muted").asBoolean());if(b.has("archived"))p.setArchived(b.get("archived").asBoolean());if(b.has("deleted"))p.setDeleted(b.get("deleted").asBoolean());participants.save(p);return ok("PATCH",Map.of("conversationId",id,"muted",p.isMuted(),"archived",p.isArchived(),"deleted",p.isDeleted()));}
 public ApiResponseDto<?> viewingTimeline(HttpServletRequest r,Long id){
member(id,accounts.authenticatedUserId(r));return ok("GET",Map.of("viewings",domain.jdbc.queryForList("SELECT id,room_id AS roomId,starts_at AS startsAt,ends_at AS endsAt,status,rental_decision AS rentalDecision FROM room_viewing_requests WHERE conversation_id=? ORDER BY starts_at DESC",id),"proposals",domain.jdbc.queryForList("SELECT id,starts_at AS startsAt,CASE WHEN status='PENDING' AND starts_at<=UTC_TIMESTAMP(6) THEN 'EXPIRED' ELSE status END AS status FROM room_viewing_proposals WHERE conversation_id=? ORDER BY starts_at DESC",id)));
 }
 @Transactional public ApiResponseDto<?> roommateConversation(HttpServletRequest r,Long requestId){Long me=accounts.authenticatedUserId(r);domain.jdbc.queryForList("SELECT id FROM roommate_requests WHERE id=? FOR UPDATE",requestId);RoommateRequest x=roommateRequests.findById(requestId).orElseThrow(()->notFound("Không tìm thấy kết nối"));if(!x.getSenderId().equals(me)&&!x.getReceiverId().equals(me))throw forbidden("Không phải thành viên kết nối");if(!"ACCEPTED".equals(x.getStatus())||x.getEndedAt()!=null)throw conflict("Kết nối đã kết thúc");Conversation c=conversations.findByRoommateRequestId(requestId).orElseGet(()->newConversation("ROOMMATE",null,null,requestId));c=conversations.save(c);ensureParticipant(c.getId(),x.getSenderId());ensureParticipant(c.getId(),x.getReceiverId());return ok("POST",conversationData(c));}
 @Transactional public ApiResponseDto<?> sharePost(HttpServletRequest r,Long id,JsonNode b){
Long me=accounts.authenticatedUserId(r);Conversation c=member(id,me);if(!"ROOMMATE".equals(c.getType()))throw bad("Chỉ chia sẻ tin trong kết nối ở ghép");ensureCanSend(c);Long postId=requiredLong(b,"postId");Post p=posts.findById(postId).filter(this::publicPost).orElseThrow(()->notFound("Tin không còn khả dụng"));String key=text(b,"clientMessageKey");if(key.isBlank())throw bad("Cần clientMessageKey");domain.jdbc.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",me);Optional<ChatMessage> old=messages.findBySenderIdAndClientMessageKey(me,key);if(old.isPresent()){ChatMessage m=old.get();if(!id.equals(m.getConversationId())||!"POST_SHARE".equals(m.getMessageType())||!postId.equals(m.getSharedPostId()))throw conflict("Khóa tin nhắn đã dùng với nội dung khác");return ok("POST",messageData(m));}ChatMessage m=new ChatMessage();m.setConversationId(id);m.setSenderId(me);m.setClientMessageKey(key);m.setMessageType("POST_SHARE");m.setSharedPostId(p.getId());m.setSentAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));m=messages.saveAndFlush(m);publishMessage(c,m,me);return ok("POST",messageData(m));
 }
 public ApiResponseDto<?> notificationList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String read=r.getParameter("isRead"),type=r.getParameter("type");return ok("GET",notifications.findByUserIdOrderByCreatedAtDesc(me).stream().filter(n->read==null||Boolean.valueOf(read)==n.isRead()).filter(n->type==null||type.equals(n.getType())).map(this::notificationData).toList());}
 public ApiResponseDto<?> notificationCounts(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);long unread=notifications.countByUserIdAndReadFalse(me);long msg=participants.findByUserId(me).stream().filter(p->participants.findByConversationId(p.getConversationId()).size()==2).mapToLong(p->unread(p,me)).sum();return ok("GET",Map.of("notificationsUnread",unread,"messagesUnread",msg));}
 @Transactional public ApiResponseDto<?> notificationRead(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);Notification n=notifications.findById(id).filter(x->x.getUserId().equals(me)).orElseThrow(()->notFound("Không tìm thấy thông báo"));if(b!=null&&b.has("isRead")&&!b.get("isRead").asBoolean())throw bad("Chỉ hỗ trợ đánh dấu đã đọc");n.setRead(true);if(n.getReadAt()==null)n.setReadAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));return ok("PUT",notificationData(notifications.save(n)));}
 @Transactional public ApiResponseDto<?> notificationReadAll(HttpServletRequest r,JsonNode b){Long me=accounts.authenticatedUserId(r);LocalDateTime cutoff;try{cutoff=b!=null&&b.hasNonNull("throughCreatedAt")?java.time.OffsetDateTime.parse(text(b,"throughCreatedAt")).withOffsetSameInstant(java.time.ZoneOffset.UTC).toLocalDateTime():LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS);}catch(Exception e){throw bad("throughCreatedAt cần thời gian có múi giờ");}int count=0;for(Notification n:notifications.findByUserIdOrderByCreatedAtDesc(me))if(!n.isRead()&&!n.getCreatedAt().isAfter(cutoff)){n.setRead(true);n.setReadAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));notifications.save(n);count++;}return ok("POST",Map.of("updatedCount",count));}
 public SseEmitter events(HttpServletRequest r){
Long me=accounts.authenticatedUserId(r);SseEmitter emitter=hub.connect(me,()->{try{return accounts.authenticatedUserId(r).equals(me);}catch(Exception e){return false;}});return emitter;
 }
 private void ensureCanSend(Conversation c){if("ROOMMATE".equals(c.getType())){Map<String,Object> state=domain.jdbc.queryForMap("SELECT status,ended_at FROM roommate_requests WHERE id=? FOR UPDATE",c.getRoommateRequestId());if(!"ACCEPTED".equals(state.get("status"))||state.get("ended_at")!=null)throw conflict("Kết nối đã kết thúc");}if(domain.exists("SELECT id FROM conversation_participants WHERE conversation_id=? AND left_at IS NOT NULL",c.getId()))throw conflict("Thành viên đã rời hội thoại");for(var p:participants.findByConversationId(c.getId()))if(!domain.exists("SELECT id FROM users WHERE id=? AND status='ACTIVE'",p.getUserId()))throw conflict("Tài khoản trong hội thoại không hoạt động");}
 private long unread(ConversationParticipant p,Long me){
return domain.jdbc.queryForObject("SELECT COUNT(*) FROM chat_messages m WHERE m.conversation_id=? AND m.sender_id<>? AND (? IS NULL OR m.sent_at>? OR m.sent_at=? AND m.id>COALESCE((SELECT last_message_id FROM api_conversation_read_cursors WHERE conversation_id=? AND user_id=?),9223372036854775807))",Long.class,p.getConversationId(),me,p.getLastReadAt(),p.getLastReadAt(),p.getLastReadAt(),p.getConversationId(),me);
 }
 private Map<String,Object> messageResult(ChatMessage m){return Map.of("message",messageData(m),"eventId","message:"+m.getId());}
 private void publishMessage(Conversation c,ChatMessage m,Long me){c.setLastMessageId(m.getId());c.setLastMessageAt(m.getSentAt());conversations.save(c);for(var p:participants.findByConversationId(c.getId())){hub.publish(p.getUserId(),"message","message:"+m.getId(),messageData(m));if(!p.getUserId().equals(me)&&!p.isMuted()&&domain.exists("SELECT id FROM users WHERE id=? AND in_app_enabled=TRUE",p.getUserId()))createNotification(p.getUserId(),"NEW_MESSAGE","Tin nhắn mới","Bạn có tin nhắn mới","CONVERSATION",c.getId(),"message:"+m.getId());}}
 private Conversation newConversation(String type,Long room,Long post,Long request){Conversation c=new Conversation();c.setType(type);c.setRoomId(room);c.setPostId(post);c.setRoommateRequestId(request);return c;}
 private void ensureParticipant(Long cid,Long uid){
domain.jdbc.update("INSERT IGNORE INTO conversation_participants(conversation_id,user_id,joined_at) VALUES (?,?,UTC_TIMESTAMP(6))",cid,uid);
 }
 private Conversation member(Long id,Long uid){
Conversation c=conversations.findById(id).orElseThrow(()->notFound("Không tìm thấy hội thoại"));var ps=participants.findByConversationId(id);if(!domain.exists("SELECT id FROM conversation_participants WHERE conversation_id=? AND user_id=? AND left_at IS NULL",id,uid))throw forbidden("Không còn là thành viên hội thoại");if(ps.size()!=2||ps.stream().noneMatch(p->p.getUserId().equals(uid)))throw forbidden("Hội thoại không thuộc ngữ cảnh riêng của hai bên");return c;
 }
 private void createNotification(Long uid,String type,String title,String content,String rt,Long rid,String key){if(notifications.findByUserIdAndEventKey(uid,key).isPresent())return;Notification n=new Notification();n.setUserId(uid);n.setType(type);n.setTitle(title);n.setContent(content);n.setResourceType(rt);n.setResourceId(rid);n.setEventKey(key);n.setCreatedAt(LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));notifications.save(n);hub.publish(uid,"notification",String.valueOf(n.getId()),notificationData(n));}
 private Map<String,Object> conversationData(Conversation c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("type",c.getType());m.put("roomId",c.getRoomId());m.put("postId",c.getPostId());m.put("roommateRequestId",c.getRoommateRequestId());m.put("lastMessageId",c.getLastMessageId());m.put("lastMessageAt",c.getLastMessageAt());m.put("participants",participants.findByConversationId(c.getId()).stream().map(p->Map.of("userId",p.getUserId(),"joinedAt",p.getJoinedAt(),"muted",p.isMuted(),"archived",p.isArchived(),"deleted",p.isDeleted())).toList());return m;}
 private Map<String,Object> messageData(ChatMessage m){Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.getId());x.put("senderId",m.getSenderId());x.put("type",m.getMessageType());x.put("content",m.getContent());x.put("sentAt",m.getSentAt());x.put("sharedPostId",m.getSharedPostId());x.put("fileIds",domain.jdbc.queryForList("SELECT id FROM files WHERE chat_message_id=?",Long.class,m.getId()));return x;}
 private Map<String,Object> notificationData(Notification n){Map<String,Object> x=new LinkedHashMap<>();x.put("id",n.getId());x.put("type",n.getType());x.put("title",n.getTitle());x.put("content",n.getContent());x.put("isRead",n.isRead());x.put("resourceType",n.getResourceType());x.put("resourceId",n.getResourceId());x.put("createdAt",n.getCreatedAt());return x;}
 private boolean publicPost(Post p){
return domain.publicPost(p.getId());
 } private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();} private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";} private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);} private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,m);} private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);} private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
